/*
 * Layout primitives for the settings page. Both are POJO components (Mithril
 * requires a `view` method — arrow functions are React syntax). Cast to `any`
 * so TS treats them as valid JSX elements: Mithril's JSX intrinsic types insist
 * on a class- or function-component shape, but Mithril accepts any object with a
 * `view()` method at runtime.
 */

export const AdminCard = {
  view(_ref) {
    let {
      attrs: {
        title,
        icon
      },
      children
    } = _ref;
    return m("div", {
      className: "AvocadoAdmin-card"
    }, m("div", {
      className: "AvocadoAdmin-card-header"
    }, icon && m("span", {
      className: "AvocadoAdmin-card-icon"
    }, m("i", {
      className: icon,
      "aria-hidden": "true"
    })), m("h3", {
      className: "AvocadoAdmin-card-title"
    }, title)), m("div", {
      className: "AvocadoAdmin-card-body"
    }, children));
  }
};

// Divider between groups of sub-settings.
export const SubDivider = {
  view() {
    return m("div", {
      className: "AvocadoAdmin-subDivider"
    });
  }
};
flarum.reg.add('ramon-avocado', 'admin/components/AdminCard', { AdminCard: AdminCard,SubDivider: SubDivider, });